/**
 * The character archetypes an animated carousel can be built around.
 *
 * Display data only. The prompt brief that actually describes each character
 * lives in server/src/characters.js and never reaches the browser — the client
 * sends an id and the server looks the brief up, so the art style the product
 * sells is not something a caller can rewrite.
 *
 * The ids here must match that file exactly. If one changes there and not here,
 * the picker sends an id the server rejects with "Pick a character."
 *
 * The portraits were generated by server/scripts/make-character-art.mjs from
 * those same briefs, so the tile someone picks is the character they get.
 */
export const CHARACTERS = [
  { id: 'ch_kid_3d', name: 'Cartoon kid', blurb: 'Bright, friendly, all-ages', img: '/characters/kid-3d.jpg' },
  { id: 'ch_mascot_bird', name: 'Mascot bird', blurb: 'Bold brand-mascot energy', img: '/characters/mascot-bird.jpg' },
  { id: 'ch_pro_woman', name: 'Professional', blurb: 'Credible, B2B-friendly', img: '/characters/pro-woman.jpg' },
  { id: 'ch_everyday_woman', name: 'Everyday woman', blurb: 'Warm and relatable', img: '/characters/everyday-woman.jpg' },
  { id: 'ch_athlete', name: 'Athlete', blurb: 'Energetic, fitness and food', img: '/characters/athlete.jpg' },
  { id: 'ch_blob', name: 'Friendly creature', blurb: 'Playful, no human likeness', img: '/characters/blob.jpg' },
  { id: 'ch_senior', name: 'Trusted elder', blurb: 'Health, finance, insurance', img: '/characters/senior.jpg' },
  { id: 'ch_dog', name: 'Mascot dog', blurb: 'Consumer, pets, food', img: '/characters/dog.jpg' },
  { id: 'ch_robot', name: 'Robot', blurb: 'Apps, SaaS, anything technical', img: '/characters/robot.jpg' },
  { id: 'ch_chef', name: 'Chef', blurb: 'Food, drink, restaurants', img: '/characters/chef.jpg' },
]

export const getCharacter = (id) => CHARACTERS.find((c) => c.id === id) || null
